/**
 * A sound or piece of music played from a file: MP3, FLAC, Ogg Vorbis, Opus, WAV, AAC and the
 * like. It opens in the background and streams, so long pieces cost little memory. Views that
 * read its state or position run again as it plays. A playing sound keeps playing after its
 * last reference is gone, until it pauses or ends.
 *
 * Copies share one reference-counted object, usable from any thread.
 */
class Sound {
public:
    Sound(const Sound& other) noexcept : raw_(rk_sound_ref(other.raw_)) {}

    Sound(Sound&& other) noexcept : raw_(std::exchange(other.raw_, nullptr)) {}

    Sound& operator=(Sound other) noexcept {
        swap(other);
        return *this;
    }

    ~Sound() {
        rk_sound_unref(raw_);
    }

    /**
     * Takes over one reference to a handle from the C API.
     */
    [[nodiscard]] static Sound adopt(rk_sound* raw) noexcept {
        return Sound(detail::Adopt{}, raw);
    }

    /**
     * The handle for the C API; this object keeps its reference.
     */
    [[nodiscard]] rk_sound* raw() const noexcept {
        return raw_;
    }

    /**
     * Gives this object's reference to the caller, leaving it empty.
     */
    [[nodiscard]] rk_sound* release() noexcept {
        return std::exchange(raw_, nullptr);
    }

    void swap(Sound& other) noexcept {
        std::swap(raw_, other.raw_);
    }

    /**
     * Opens a sound file in the background.
     *
     * Thread-safe.
     */
    explicit Sound(std::string_view path);

    /**
     * Starts or resumes playing; from the start once it has ended. A sound still opening starts
     * once it is open.
     *
     * Thread-safe.
     */
    void play();

    /**
     * Pauses where it is.
     *
     * Thread-safe.
     */
    void pause();

    /**
     * Pauses and returns to the start.
     *
     * Thread-safe.
     */
    void stop();

    /**
     * Moves to a point, at most its end.
     *
     * Thread-safe.
     *
     * @param seconds From the start; not below 0.
     */
    void seek(double seconds);

    /**
     * Runs a callback on a window each time it plays to its end, replacing the previous one.
     *
     * Thread-safe.
     *
     * @param window The window whose context the callback receives.
     * @param callback Reacts to an event. The window's view runs again afterwards unless
     * rikka::Context::skip_view() is called. It may run on any thread.
     */
    template <class F>
        requires std::invocable<F&, Context&>
    void on_end(const Window& window, F&& callback);

    /**
     * Where it is in its playback.
     *
     * Thread-safe.
     */
    [[nodiscard]] PlaybackState state() const;

    /**
     * Whether it plays, or will once it is open.
     *
     * Thread-safe.
     */
    [[nodiscard]] bool is_playing() const;

    /**
     * The point it has reached, in seconds from the start.
     *
     * Thread-safe.
     */
    [[nodiscard]] double position() const;

    /**
     * Its length in seconds; 0 while unknown.
     *
     * Thread-safe.
     */
    [[nodiscard]] double duration() const;

    /**
     * Its loudness, from 0 to 1; 1 unless set.
     *
     * Thread-safe.
     */
    [[nodiscard]] double volume() const;

    /**
     * Not below 0 nor above 1.
     *
     * Thread-safe.
     */
    void set_volume(double volume);

    /**
     * Whether it starts over when it reaches its end.
     *
     * Thread-safe.
     */
    [[nodiscard]] bool looping() const;

    /**
     * Whether it starts over when it reaches its end.
     *
     * Thread-safe.
     */
    void set_looping(bool looping);

    /**
     * Why it cannot be played; empty unless its state is rikka::PlaybackState::failed.
     *
     * Thread-safe.
     */
    [[nodiscard]] std::string error_message() const;

private:
    Sound(detail::Adopt, rk_sound* raw) noexcept : raw_(raw) {}

    rk_sound* raw_ = nullptr;
};

