    /**
     * Whether the view is drawn in a dark theme.
     */
    [[nodiscard]] bool is_dark() const;

    /**
     * A column: children stack top to bottom.
     *
     * @param body Declares the children.
     */
    template <class Body>
        requires std::invocable<Body&>
    Element column(Body&& body);

