/**
 * The version of the loaded library, packed as major << 22 | minor << 12 | patch.
 *
 * Thread-safe.
 */
inline std::uint32_t version() {
    return rk_version();
}

/**
 * Describes the last failure on the calling thread.
 *
 * Thread-safe.
 *
 * @return Valid until the next failing call on this thread; empty if nothing failed.
 */
inline std::string_view last_error() {
    return detail::view(rk_last_error());
}

/**
 * Opens a web address in the desktop's browser, or another URL in the program that handles its
 * scheme, such as mailto: in the mail program.
 *
 * Thread-safe.
 *
 * @param url An absolute URL such as https://example.org.
 * @throws rikka::Error with the failing status.
 */
inline void open_url(std::string_view url) {
    detail::check(rk_open_url(detail::str(url)));
}

/**
 * Opens a file or folder in the desktop's default program for it.
 *
 * Thread-safe.
 *
 * @param path Absolute, or relative to the working directory.
 * @throws rikka::Error with the failing status.
 */
inline void open_file(std::string_view path) {
    detail::check(rk_open_file(detail::str(path)));
}

